import pandas as pd, numpy as np, re, requests, matplotlib.pyplot as plt
from collections import Counter
H={"User-Agent":"openscientist/1.0"}
fa=pd.read_csv("https://ftp.ensembl.org/pub/current_fasta/saccharomyces_cerevisiae/dna/Saccharomyces_cerevisiae.R64-1-1.dna.toplevel.fa.gz",
               sep="\x01",header=None,compression="gzip",names=["l"],dtype=str,quoting=3).l.tolist()
genome={}; cur=None; buf=[]
for line in fa:
    if line.startswith(">"):
        if cur: genome[cur]="".join(buf)
        cur=line[1:].split()[0]; buf=[]
    else: buf.append(line.strip().upper())
genome[cur]="".join(buf)
CH=[c for c in genome if c!="Mito"]
gtf=pd.read_csv("https://ftp.ensembl.org/pub/release-115/gtf/saccharomyces_cerevisiae/Saccharomyces_cerevisiae.R64-1-1.115.gtf.gz",
                sep="\t",comment="#",header=None,compression="gzip",
                names=["chrom","src","feat","start","end","score","strand","frame","attr"],dtype={"chrom":str})
g=gtf[gtf.feat=="gene"].copy()
g["gene_id"]=g.attr.str.extract(r'gene_id "([^"]+)"'); g["gene_name"]=g.attr.str.extract(r'gene_name "([^"]+)"')
g["biotype"]=g.attr.str.extract(r'gene_biotype "([^"]+)"'); g["name"]=g.gene_name.fillna(g.gene_id)
g=g[(g.biotype=="protein_coding")&(g.chrom.isin(CH))].reset_index(drop=True)
def revcomp(s): return s.translate(str.maketrans("ACGTN","TGCAN"))[::-1]
def prom(r,UP):
    c=genome[r.chrom]
    return c[max(0,r.start-1-UP):r.start-1] if r.strand=="+" else revcomp(c[r.end:min(len(c),r.end+UP)])
IUP={"A":"A","C":"C","G":"G","T":"T","W":"[AT]","N":"[ACGT]","R":"[AG]"}
def rx(m): return "".join(IUP[c] for c in m)
def rcm(m):
    cm={"A":"T","T":"A","G":"C","C":"G","W":"W","N":"N","R":"Y"}
    return "".join(cm[c] for c in reversed(m))
def cnt_both(s,m): return len(re.findall("(?=%s)"%rx(m),s))+len(re.findall("(?=%s)"%rx(rcm(m)),s))

TARGETS={"FLO11":"YIR019C","FLO10":"YKR102W","TEC1":"YBR083W","ROF1":"YHR177W","MIT1":"YEL007W",
         "FLO1":"YAR050W","FLO5":"YHR211W","FLO9":"YAL063C","MUC1":"YIR019C"}
out={}
fig,axes=plt.subplots(1,2,figsize=(13,5))
for ax,(UP,core) in zip(axes,[(700,"GTTTA"),(1000,"GTTTA")]):
    recs=[]
    for r in g.itertuples():
        p=prom(r,UP)
        recs.append(dict(gene_id=r.gene_id,name=r.name,hits=cnt_both(p,core),
                         hits8=cnt_both(p,"AAGTTTAA"),dens=cnt_both(p,core)/max(len(p),1)))
    P=pd.DataFrame(recs).sort_values("hits",ascending=False).reset_index(drop=True)
    P["rank"]=P.hits.rank(ascending=False,method="min").astype(int)
    P["pct"]=100*P.hits.rank(ascending=False,method="average")/len(P)
    out[UP]=P
    print(f"\n### promoter window = {UP} bp upstream, motif {core} (both strands) ###")
    print("median hits per promoter:",P.hits.median(),"| mean %.2f"%P.hits.mean(),"| max",P.hits.max(),
          "| promoters with >=1 hit: %d (%.1f%%)"%( (P.hits>0).sum(),100*(P.hits>0).mean()))
    print("top 15 promoters:")
    print(P.head(15)[["rank","name","gene_id","hits","hits8"]].to_string(index=False))
    print("target genes:")
    sub=P[P.gene_id.isin(TARGETS.values())]
    print(sub[["rank","pct","name","gene_id","hits","hits8"]].sort_values("rank").to_string(index=False))
    ax.hist(P.hits,bins=np.arange(-0.5,P.hits.max()+1.5),color="#9aa7b1",edgecolor="white")
    for nm,gid in [("FLO11","YIR019C"),("FLO10","YKR102W"),("TEC1","YBR083W")]:
        h=P.loc[P.gene_id==gid,"hits"]
        if len(h): ax.axvline(h.iloc[0]+np.random.uniform(-0.12,0.12),ls="--",lw=1.6,
                              color={"FLO11":"#c0392b","FLO10":"#2874a6","TEC1":"#1e8449"}[nm],label=f"{nm} ({int(h.iloc[0])} hits)")
    ax.set_xlabel(f"GTTTA occurrences in {UP} bp promoter (both strands)")
    ax.set_ylabel("number of genes"); ax.set_title(f"{UP} bp upstream windows, n={len(P)} genes"); ax.legend(fontsize=8)
plt.suptitle("Predicted WOPR consensus GTTTA is present in most S. cerevisiae promoters")
plt.tight_layout(); plt.show()
globals()['OUT']=out
